//! macOS general pasteboard: snapshot reads and marked writes.

use crate::imaging;
use crate::model::{Captured, ClipKind};
use objc2::rc::Retained;
use objc2_app_kit::NSPasteboard;
use objc2_foundation::{NSData, NSString};

/// Written alongside content we put on the pasteboard ourselves, so the
/// watcher records a restore instead of a new copy.
pub const MARKER: &str = "dev.base698.copypasta.restore";

const SKIP_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
];
const IMAGE_TYPES: &[&str] = &["public.png", "public.tiff", "public.jpeg", "com.compuserve.gif", "public.heic"];

#[derive(Debug, Clone, Default)]
pub struct Snapshot {
    pub change_count: isize,
    pub types: Vec<String>,
    pub text: Option<String>,
    pub image: Option<Vec<u8>>,
    pub html: Option<String>,
    /// Page the content was copied from (Chromium browsers set this).
    pub source_url: Option<String>,
    pub files: Vec<String>,
}

fn general() -> Retained<NSPasteboard> {
    NSPasteboard::generalPasteboard()
}

pub fn change_count() -> isize {
    general().changeCount()
}

fn ns(s: &str) -> Retained<NSString> {
    NSString::from_str(s)
}

pub fn read() -> Snapshot {
    let pb = general();
    let mut snap = Snapshot { change_count: pb.changeCount(), ..Default::default() };
    if let Some(types) = pb.types() {
        snap.types = types.iter().map(|t| t.to_string()).collect();
    }
    let has = |t: &str| snap.types.iter().any(|x| x == t);
    if snap.types.iter().any(|t| SKIP_TYPES.contains(&t.as_str())) {
        return snap;
    }
    snap.text = pb.stringForType(&ns("public.utf8-plain-text")).map(|s| s.to_string());
    snap.html = if has("public.html") { pb.stringForType(&ns("public.html")).map(|s| s.to_string()) } else { None };
    snap.source_url = ["org.chromium.source-url", "public.url"]
        .iter()
        .filter(|t| has(t))
        .find_map(|t| pb.stringForType(&ns(t)).map(|s| s.to_string()))
        .filter(|u| u.starts_with("http"));
    if has("public.file-url") {
        if let Some(items) = pb.pasteboardItems() {
            for item in items.iter() {
                if let Some(u) = item.stringForType(&ns("public.file-url")) {
                    snap.files.push(file_url_to_path(&u.to_string()));
                }
            }
        }
    }
    if snap.files.is_empty() {
        if let Some(t) = IMAGE_TYPES.iter().find(|t| has(t)) {
            snap.image = pb.dataForType(&ns(t)).map(|d| d.to_vec());
        }
    }
    snap
}

impl Snapshot {
    pub fn is_ours(&self) -> bool {
        self.types.iter().any(|t| t == MARKER)
    }

    pub fn is_skipped(&self) -> bool {
        self.types.iter().any(|t| SKIP_TYPES.contains(&t.as_str()))
    }

    /// New clipboard content worth recording (not ours, not a password).
    pub fn to_captured(&self) -> Option<Captured> {
        if self.is_ours() {
            return None;
        }
        self.content()
    }

    /// Clipboard content regardless of who wrote it.
    pub fn content(&self) -> Option<Captured> {
        if self.is_skipped() {
            return None;
        }
        let types = self.types.clone();
        if !self.files.is_empty() {
            return Some(Captured { kind: ClipKind::File, text: Some(self.files.join("\n")), types, ..Default::default() });
        }
        let text = self.text.as_deref().map(str::trim).filter(|t| !t.is_empty());
        let rich_text = self.types.iter().any(|t| t == "public.rtf" || t == "com.apple.flat-rtfd");
        if let Some(bytes) = &self.image {
            let text_is_url = text.map(is_url).unwrap_or(false);
            if text.is_none() || text_is_url || !rich_text {
                if let Ok(img) = imaging::to_png(bytes) {
                    let src = self
                        .html
                        .as_deref()
                        .and_then(img_src)
                        .or_else(|| text.filter(|t| is_url(t)).map(str::to_string));
                    return Some(Captured {
                        kind: ClipKind::Image,
                        text: src,
                        width: Some(img.width),
                        height: Some(img.height),
                        png: Some(img.png),
                        types,
                    });
                }
            }
        }
        let raw = self.text.clone()?;
        if raw.trim().is_empty() {
            return None;
        }
        let kind = if is_url(raw.trim()) { ClipKind::Url } else { ClipKind::Text };
        Some(Captured { kind, text: Some(raw), types, ..Default::default() })
    }
}

pub fn is_url(t: &str) -> bool {
    let t = t.trim();
    (t.starts_with("http://") || t.starts_with("https://")) && !t.contains(char::is_whitespace)
}

fn img_src(html: &str) -> Option<String> {
    let i = html.find("<img")?;
    let rest = &html[i..];
    let j = rest.find("src=")? + 4;
    let quote = rest[j..].chars().next()?;
    let body = &rest[j + 1..];
    let end = body.find(quote)?;
    Some(body[..end].replace("&amp;", "&")).filter(|s| s.starts_with("http"))
}

fn file_url_to_path(u: &str) -> String {
    let p = u.strip_prefix("file://").unwrap_or(u);
    let bytes = p.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let Ok(b) = u8::from_str_radix(&p[i + 1..i + 3], 16) {
                out.push(b);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).trim_end_matches('/').to_string()
}

/// Put text back on the pasteboard (marked as ours).
pub fn write_text(text: &str) -> bool {
    let pb = general();
    pb.clearContents();
    let ok = pb.setString_forType(&ns(text), &ns("public.utf8-plain-text"));
    pb.setString_forType(&ns("1"), &ns(MARKER));
    ok
}

/// Put a PNG back on the pasteboard (marked as ours).
pub fn write_png(png: &[u8], url: Option<&str>) -> bool {
    let pb = general();
    pb.clearContents();
    let data = NSData::with_bytes(png);
    let ok = pb.setData_forType(Some(&data), &ns("public.png"));
    if let Some(u) = url {
        pb.setString_forType(&ns(u), &ns("public.utf8-plain-text"));
    }
    pb.setString_forType(&ns("1"), &ns(MARKER));
    ok
}

#[cfg(test)]
mod tests {
    #[test]
    fn helpers() {
        assert_eq!(super::file_url_to_path("file:///Users/a/My%20File.txt"), "/Users/a/My File.txt");
        assert_eq!(
            super::img_src(r#"<meta><img alt="x" src="https://e.com/a.png?x=1&amp;y=2">"#).as_deref(),
            Some("https://e.com/a.png?x=1&y=2")
        );
    }
}
